import{_ as s,o as a,c as i,ag as t}from"./chunks/framework.DNmTgtHf.js";const k=JSON.parse('{"title":"LinkedHashMap","description":"","frontmatter":{},"headers":[],"relativePath":"java/foundations/linked_hashmap/LinkedHashMap.md","filePath":"java/foundations/linked_hashmap/LinkedHashMap.md"}'),n={name:"java/foundations/linked_hashmap/LinkedHashMap.md"};function r(h,e,d,l,o,p){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="linkedhashmap" tabindex="-1">LinkedHashMap <a class="header-anchor" href="#linkedhashmap" aria-label="Permalink to &quot;LinkedHashMap&quot;">​</a></h1><hr><h2 id="what-linkedhashmap-adds-to-hashmap" tabindex="-1">What LinkedHashMap adds to HashMap <a class="header-anchor" href="#what-linkedhashmap-adds-to-hashmap" aria-label="Permalink to &quot;What LinkedHashMap adds to HashMap&quot;">​</a></h2><p><code>LinkedHashMap&lt;K, V&gt;</code> extends <code>HashMap&lt;K, V&gt;</code> — same bucket array, same hash function, same O(1) average get/put. The only structural addition is a <strong>doubly-linked list threaded through every entry</strong>.</p><p>Each entry has two extra pointers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HashMap bucket array</span></span>
<span class="line"><span>  [0] -&gt; null</span></span>
<span class="line"><span>  [1] -&gt; Entry{key=A, val=1, before=null, after=Entry{B}} &lt;-&gt; Entry{key=B, val=2, before=Entry{A}, after=Entry{C}} &lt;-&gt; ...</span></span>
<span class="line"><span>  [2] -&gt; ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Linked list: head -&gt; A &lt;-&gt; B &lt;-&gt; C &lt;-&gt; ... &lt;-&gt; Z &lt;- tail</span></span></code></pre></div><ul><li><strong><code>head</code></strong> — eldest entry (inserted or accessed least recently)</li><li><strong><code>tail</code></strong> — newest entry (inserted or accessed most recently)</li></ul><p>Iteration follows the linked list, not the bucket array — predictable, stable order, unlike plain <code>HashMap</code>, which reorders entries freely during resizing.</p><hr><h2 id="insertion-order-vs-access-order" tabindex="-1">Insertion order vs access order <a class="header-anchor" href="#insertion-order-vs-access-order" aria-label="Permalink to &quot;Insertion order vs access order&quot;">​</a></h2><p><code>LinkedHashMap</code> has two modes, selected at construction time.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Controlled by</th><th>Behaviour</th></tr></thead><tbody><tr><td>Insertion order</td><td><code>accessOrder=false</code> (default)</td><td>Entries iterate in the order keys were <strong>first inserted</strong>. Reinserting an existing key does not move it.</td></tr><tr><td>Access order</td><td><code>accessOrder=true</code></td><td>Every <code>get()</code> or <code>put()</code> of an <strong>existing</strong> key moves that entry to the <strong>tail</strong> of the list (most recently used).</td></tr></tbody></table><p>Constructor for access order:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LinkedHashMap&lt;&gt;(initialCapacity, loadFactor, accessOrder)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// e.g.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">new LinkedHashMap&lt;&gt;(16, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.75f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// access-order mode</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LinkedHashMap&lt;&gt;(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.75f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// insertion-order mode (default)</span></span></code></pre></div><p>In access-order mode, the list orders entries from least recently used (head) to most recently used (tail) — exactly what an LRU eviction policy needs.</p><hr><h2 id="removeeldestentry-hook" tabindex="-1"><code>removeEldestEntry()</code> hook <a class="header-anchor" href="#removeeldestentry-hook" aria-label="Permalink to &quot;\`removeEldestEntry()\` hook&quot;">​</a></h2><p>After every <code>put()</code> (including a put that updates an existing key), <code>LinkedHashMap</code> calls:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">protected</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> boolean</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> removeEldestEntry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Map.Entry</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">K, V</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> eldest)</span></span></code></pre></div><p><code>eldest</code> is the <strong>head</strong> of the linked list — the entry in the map the longest (insertion order) or accessed least recently (access order).</p><ul><li>Default implementation: always returns <code>false</code>. Nothing is ever evicted.</li><li>Override to return <code>true</code> when eviction should happen.</li></ul><p>When it returns <code>true</code>, the map removes <code>eldest</code> automatically before returning from <code>put()</code>. No manual bookkeeping needed.</p><hr><h2 id="lru-cache-pattern" tabindex="-1">LRU cache pattern <a class="header-anchor" href="#lru-cache-pattern" aria-label="Permalink to &quot;LRU cache pattern&quot;">​</a></h2><p>The standard bounded LRU cache using <code>LinkedHashMap</code>:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capacity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Map&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; lruCache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LinkedHashMap&lt;&gt;(capacity, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.75f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    @</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Override</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    protected</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> boolean</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> removeEldestEntry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Map.Entry&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">eldest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capacity;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>How it works:</p><ul><li><code>accessOrder=true</code> — every <code>get()</code> or <code>put()</code> moves the touched entry to the tail.</li><li><code>removeEldestEntry</code> fires after every <code>put()</code>. When size exceeds capacity, the head (least recently used) is evicted.</li><li><code>get()</code> and <code>put()</code> remain O(1) average. Eviction is O(1) — removing the head of a doubly-linked list is pointer surgery.</li></ul><p>No external data structures, no manual LRU tracking.</p><hr><h2 id="thread-safety" tabindex="-1">Thread safety <a class="header-anchor" href="#thread-safety" aria-label="Permalink to &quot;Thread safety&quot;">​</a></h2><p><code>LinkedHashMap</code> is <strong>not thread-safe</strong> — same guarantee as <code>HashMap</code>. Concurrent reads are fine; any concurrent modification is not.</p><p>For a thread-safe LRU cache, wrap it:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Map&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">K</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">V</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; safe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Collections.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">synchronizedMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(lruCache);</span></span></code></pre></div><p>Critical caveat: iteration over a <code>synchronizedMap</code>-wrapped map is <strong>not automatically synchronized</strong>. You must manually lock:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">synchronized</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (safe) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (Map.Entry&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">K</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">V</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; e </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> safe.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">entrySet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) { ... }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>For high-concurrency scenarios with access-order eviction, use a dedicated library. Caffeine&#39;s <code>Cache</code> / <code>LoadingCache</code> is built on a concurrent linked hash map structure; Guava&#39;s older <code>CacheBuilder</code> does the same. There is no JDK built-in <code>ConcurrentLinkedHashMap</code>; pull in Caffeine (the de-facto standard) rather than rolling your own.</p><hr><h2 id="when-to-use-linkedhashmap" tabindex="-1">When to use LinkedHashMap <a class="header-anchor" href="#when-to-use-linkedhashmap" aria-label="Permalink to &quot;When to use LinkedHashMap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Use case</th><th>Reason</th></tr></thead><tbody><tr><td>Predictable iteration order (insertion order)</td><td>Building an ordered response map, deduplicating while preserving sequence</td></tr><tr><td>Bounded LRU cache</td><td><code>accessOrder=true</code> + <code>removeEldestEntry</code> override — all in one class</td></tr><tr><td>Access-order tracking without custom bookkeeping</td><td>The linked list does the work; you just read or iterate</td></tr></tbody></table><p>Do not use it when:</p><ul><li>You need high concurrency — use Caffeine or a <code>ConcurrentHashMap</code>-backed structure.</li><li>You need a true LRU cache with thread safety — the <code>synchronizedMap</code> wrapper serialises all operations, killing throughput under contention.</li></ul><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. What does LinkedHashMap add over HashMap structurally?</strong> A. A doubly-linked list through every entry (<code>before</code>/<code>after</code> pointers), with a <code>head</code> and <code>tail</code>. Iteration follows the list, not the bucket array.</p><p><strong>Q. Insertion order vs access order — what&#39;s the difference?</strong> A. Insertion order (default): position set on first insert, reinsertion doesn&#39;t move it. Access order (<code>accessOrder=true</code>): every <code>get()</code> or <code>put()</code> of an existing key moves it to the tail.</p><p><strong>Q. How do you implement a bounded LRU cache with LinkedHashMap?</strong> A. Use <code>accessOrder=true</code> so <code>get()</code>/<code>put()</code> promotes entries to the tail, then override <code>removeEldestEntry()</code> to return <code>true</code> when <code>size() &gt; capacity</code>. The head (LRU entry) is evicted automatically.</p><p><strong>Q. When is <code>removeEldestEntry</code> called and what does it receive?</strong> A. After every <code>put()</code>. It receives the current head of the linked list — the eldest (least recently used) entry. If it returns <code>true</code>, that entry is removed.</p><p><strong>Q. Is LinkedHashMap thread-safe?</strong> A. No. Wrap with <code>Collections.synchronizedMap()</code> for basic safety, but manually synchronize any iteration block. For high-concurrency caches, use Caffeine instead.</p>`,49)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
